  return { ok: faltando.length === 0, faltando };
}
function servico(cfg, codigo) { return (cfg.servicos || []).find(s => s.codigo === codigo); }
function profissional(cfg, id) { return (cfg.profissionais || []).find(p => p.id === id); }
// Texto que o agente pode usar sobre a clínica (somente o que está configurado).
function infoClinica(cfg, topico) {
  const c = cfg.clinica || {};
  const nd = 'Informação não configurada pela clínica. Não invente: ofereça encaminhar para a equipe.';
  const val = v => (vazio(v) ? nd : v);
  switch (topico) {
    case 'endereco': return { endereco: val(c.endereco), maps_link: val(c.maps_link) };
    case 'telefone': return { telefone: val(c.telefone) };
    case 'horario_funcionamento': return { horario: val(cfg.agenda && cfg.agenda.horario_funcionamento_texto) };
    case 'profissionais': return { profissionais: (cfg.profissionais || []).filter(p => !vazio(p.nome)).map(p => ({ id: p.id, nome: p.nome, especialidade: vazio(p.especialidade) ? undefined : p.especialidade })) };
    case 'servicos': return { servicos: (cfg.servicos || []).map(s => ({ codigo: s.codigo, nome: s.nome, agendavel_online: s.agendavel_online !== false, descricao: vazio(s.descricao) ? undefined : s.descricao })) };
    case 'precos': return { precos: (cfg.servicos || []).filter(s => !vazio(s.preco_texto)).map(s => ({ servico: s.nome, preco: s.preco_texto })), observacao: 'Se o serviço não aparece aqui, o preço não foi informado: não invente, ofereça avaliação ou equipe.' };
    case 'formas_pagamento': return { formas_pagamento: val(c.formas_pagamento) };
    case 'orientacoes_consulta': return { orientacoes: val(cfg.agenda && cfg.agenda.orientacoes_consulta) };
    default: return { erro: 'topico_desconhecido', topicos: ['endereco', 'telefone', 'horario_funcionamento', 'profissionais', 'servicos', 'precos', 'formas_pagamento', 'orientacoes_consulta'] };
  }
}

// ---- lib/slots.js ----
const DIAS = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];
const p2 = n => String(n).padStart(2, '0');
// "Relógio local" = UTC deslocado pelo offset fixo da clínica (Brasil sem horário de verão: -180).
function local(ms, off) { return new Date(ms + off * 60000); }
function hm(s) { const [h, m] = s.split(':').map(Number); return h * 60 + m; }
function toIsoLocal(ms, off) {
  const d = local(ms, off), s = off <= 0 ? '-' : '+', a = Math.abs(off);
  return `${d.getUTCFullYear()}-${p2(d.getUTCMonth() + 1)}-${p2(d.getUTCDate())}T${p2(d.getUTCHours())}:${p2(d.getUTCMinutes())}:00${s}${p2(Math.floor(a / 60))}:${p2(a % 60)}`;
}
function rotulo(startMs, off) {
  const d = local(startMs, off);
  return `${DIAS[d.getUTCDay()]}, ${p2(d.getUTCDate())}/${p2(d.getUTCMonth() + 1)} às ${p2(d.getUTCHours())}:${p2(d.getUTCMinutes())}`;
}
function dataHoraTexto(startMs, off) {
  const d = local(startMs, off);
  return { data: `${p2(d.getUTCDate())}/${p2(d.getUTCMonth() + 1)}/${d.getUTCFullYear()} (${DIAS[d.getUTCDay()]})`, hora: `${p2(d.getUTCHours())}:${p2(d.getUTCMinutes())}` };
}
function slotId(profId, startIso) { return sha256(`${profId}|${new Date(startIso).toISOString()}`).slice(0, 12); }

// busy: { [profissional_id]: [{start, end}] }  (ISO)  |  horario: {"1":[["08:00","12:00"]],...}  (0=domingo)
function calcularSlots({ busy, profissionalIds, horario, feriados = [], duracaoMin, passoMin = 30, deMs, ateMs, offset, antecedenciaMin = 120, agoraMs }) {
  const slots = [], minStart = agoraMs + antecedenciaMin * 60000;
  const dia0 = Math.floor(local(deMs, offset).getTime() / 86400000) * 86400000 - offset * 60000; // 00:00 local do primeiro dia, em UTC ms
  for (let dayMs = dia0; dayMs < ateMs; dayMs += 86400000) {
    const l = local(dayMs, offset), dow = String(l.getUTCDay());
    const isoDia = `${l.getUTCFullYear()}-${p2(l.getUTCMonth() + 1)}-${p2(l.getUTCDate())}`;
    if (feriados.includes(isoDia)) continue;
    for (const [ini, fim] of horario[dow] || []) {
      for (let m = hm(ini); m + duracaoMin <= hm(fim); m += passoMin) {
        const s = dayMs + m * 60000, e = s + duracaoMin * 60000;
        if (s < minStart || s < deMs || e > ateMs) continue;
        for (const pid of profissionalIds) {
          const ocupado = (busy[pid] || []).some(b => Date.parse(b.start) < e && Date.parse(b.end) > s);
          if (!ocupado) slots.push({ slot_id: slotId(pid, new Date(s).toISOString()), profissional_id: pid, inicio: toIsoLocal(s, offset), fim: toIsoLocal(e, offset), inicio_ms: s, rotulo: rotulo(s, offset) });
        }
      }
    }
  }
  return slots.sort((a, b) => a.inicio_ms - b.inicio_ms);
}
function periodoOk(slot, periodo, offset) {
  if (!periodo) return true;
  const h = local(slot.inicio_ms, offset).getUTCHours();
  return periodo === 'manha' ? h < 12 : periodo === 'tarde' ? h >= 12 && h < 18 : periodo === 'noite' ? h >= 18 : true;
}
// Duas opções: a primeira disponível e a próxima em outro dia (ou, se não houver, ≥ 2h depois).
function escolherDuas(slots, { periodo, urgencia, offset }) {
  const lista = slots.filter(s => periodoOk(s, periodo, offset));
  if (lista.length <= 2) return lista;
  const a = lista[0];
  if (urgencia) return [a, lista.find(s => s !== a && s.inicio_ms >= a.inicio_ms + 3600000) || lista[1]];
  const dia = s => local(s.inicio_ms, offset).getUTCDate();
  const b = lista.find(s => dia(s) !== dia(a)) || lista.find(s => s.inicio_ms >= a.inicio_ms + 7200000) || lista[1];
  return [a, b];
}

// ---- lib/consent.js ----
function interpretarConsentimento(texto) {
  const t = norm(texto).replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!t) return 'indefinido';
  if (/\b(nao|nunca|discordo|recuso|nao aceito|nao concordo|prefiro nao)\b/.test(t)) return 'nao';
  if (/^(sim|ok|okay|claro|pode|pode sim|aceito|concordo|tudo bem|beleza|blz|certo|combinado|autorizo|de acordo|continuar|vamos|segue|perfeito|show)\b/.test(t) || /\b(concordo|aceito|autorizo|de acordo)\b/.test(t)) return 'sim';
  return 'indefinido';
}
// Confirmação de agendamento: mais estrita que consentimento.
function confirmacaoExplicita(texto) {
  const raw = String(texto || '');
  const t = norm(raw).replace(/[^a-z0-9? ]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!t || t.includes('?')) return false;
  if (/\b(mas|porem|outro|outra|trocar|muda|mudar|nao|so que|talvez|acho|depois)\b/.test(t)) return false;
  return /^(sim|confirmo|confirmado|confirma|pode|pode sim|pode confirmar|pode marcar|pode agendar|isso|isso mesmo|fechado|combinado|perfeito|certo|ok|okay|ta bom|ta certo|esta certo|estou de acordo|de acordo|correto|exato|beleza|blz|quero|quero sim)\b/.test(t);
}
function textoAviso(cfg) {
  const c = cfg.clinica, p = cfg.privacidade;
  return `Olá! 😊 Eu sou a assistente virtual da ${c.nome} (um atendimento automatizado, não sou uma pessoa).\n\n` +
    `Para ajudar com seu atendimento, vou usar os dados que você informar (como nome, telefone e o motivo da consulta) apenas para triagem e agendamento. ` +
    `Detalhes e seus direitos: ${p.politica_url}\n\n` +
    `Posso continuar? Responda *sim* para seguir, ou *atendente* para falar com uma pessoa.`;
}

// ---- lib/booking.js ----
// ID determinístico do evento no Google Agenda (base32hex: 0-9a-v; hex serve).
// Tentar criar o mesmo (profissional, horário) duas vezes gera 409 -> trava atômica contra corrida.
function eventoId(profId, inicioIso) { return sha256(`vs|${profId}|${new Date(inicioIso).toISOString()}`).slice(0, 32); }
function novoAtendimentoId(telefone, conversaId) { return 'ATD-' + sha256(`${telefone}|${conversaId}`).slice(0, 10).toUpperCase(); }

function nomeCompletoOk(n) { return /^\S{2,}(\s+\S{2,})+$/.test(String(n || '').trim()); }

function validarProposta(state, args, cfg, servicoFn) {
  const { acao } = args;
  if (!['agendar', 'remarcar', 'cancelar'].includes(acao)) return { ok: false, erro: 'acao_invalida' };
  if (state.consentimento !== 'sim') return { ok: false, erro: 'sem_consentimento' };
  if (acao === 'agendar' || acao === 'remarcar') {
    const slot = (state.slots_oferecidos || []).find(s => s.slot_id === args.slot_id);
    if (!slot) return { ok: false, erro: 'slot_nao_oferecido', dica: 'Use apenas slot_id retornado por consultar_agenda nesta conversa.' };
    const nome = args.nome_completo || state.paciente.nome;
    if (!nomeCompletoOk(nome)) return { ok: false, erro: 'nome_completo_necessario' };
    const codigo = args.servico_codigo || state.paciente.servico_codigo;
    if (!codigo || !servicoFn(cfg, codigo)) return { ok: false, erro: 'servico_invalido' };
    if (acao === 'remarcar' && !args.evento_id_atual) return { ok: false, erro: 'evento_atual_necessario' };
    return { ok: true, pendente: { acao, slot, nome, servico_codigo: codigo, evento_id_atual: args.evento_id_atual || null } };
  }
  if (!args.evento_id_atual) return { ok: false, erro: 'evento_atual_necessario' };
  return { ok: true, pendente: { acao, evento_id_atual: args.evento_id_atual } };
}

// Só executa se: há proposta feita em turno ANTERIOR, ainda válida, e a mensagem atual do paciente é um "sim" inequívoco.
function validarExecucao(state, textoAtual, agoraMs, ttlMin = 30) {
  const p = state.pendente;
  if (!p) return { ok: false, erro: 'nada_pendente' };
  if (state.consentimento !== 'sim') return { ok: false, erro: 'sem_consentimento' };
  if (!(state.turno > p.proposto_no_turno)) return { ok: false, erro: 'confirmacao_no_mesmo_turno' };
  if (agoraMs - Date.parse(p.proposto_em) > ttlMin * 60000) return { ok: false, erro: 'proposta_expirada' };
  if (!confirmacaoExplicita(textoAtual)) return { ok: false, erro: 'confirmacao_nao_explicita' };
  return { ok: true, pendente: p };
}

function montarEvento({ evento_id, nome, servico, prof, inicioIso, fimIso, telefone, atendimentoId, cfg }) {
  return {
    id: evento_id,
    summary: `${nome} — ${servico.nome}`,
    location: cfg.clinica.endereco,
    description: `Agendado pelo assistente virtual. Atendimento: ${atendimentoId}. Profissional: ${prof.nome}.`,
    start: { dateTime: inicioIso }, end: { dateTime: fimIso },
    reminders: { useDefault: false },
    extendedProperties: { private: { clinica: 'vamos-sorrir', telefone, telefone_hash: phoneHash(telefone), servico_codigo: servico.codigo, atendimento_id: atendimentoId, profissional_id: prof.id, nome_paciente: nome } },
  };
}
// Mensagem determinística de confirmação (não passa pelo LLM).
function mensagemConfirmacao({ nome, inicioMs, offset, prof, cfg, remarcado }) {
  const { data, hora } = dataHoraTexto(inicioMs, offset);
  const orient = cfg.agenda.orientacoes_consulta && !String(cfg.agenda.orientacoes_consulta).includes('__PREENCHER__') ? `\n\nℹ️ ${cfg.agenda.orientacoes_consulta}` : '';
  return `Perfeito${nome ? ', ' + nome.split(' ')[0] : ''}! 😊 Sua consulta na ${cfg.clinica.nome} está ${remarcado ? 'remarcada e ' : ''}confirmada!\n\n📅 Data: ${data}\n⏰ Horário: ${hora}\n🦷 Profissional: ${prof.nome}\n📍 Endereço: ${cfg.clinica.endereco}${orient}\n\nSerá um prazer receber você!`;
}

